        && SubtagMatches(s, 0, limit, "-hk"))
        {
          tags.Add(T("ZHH "));
          return true;
        }
        if (Starts(s, 1, "h-")
        && SubtagMatches(s, 0, limit, "-mo"))
        {
          tags.AddRange([T("ZHTM"), T("ZHH ")]);
          return true;
        }
        if (Starts(s, 1, "h-")
        && SubtagMatches(s, 0, limit, "-tw"))
        {
          tags.Add(T("ZHT "));
          return true;
        }
        break;
      }
      return false;
    }
}
